{
  "avaliacoes": [
    {
      "id": "E2189e8584b8d8e28",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Um arranjo de processamento pode incluir separação trifásica com tratamento de óleo para adequação a padrões de qualidade antes da transferência às refinarias; o texto também descreve um arranjo em que óleo previamente tratado passa por nova separação água-óleo em tratadores eletrostáticos quando ainda não atende ao padrão exigido.",
          "trechos": [
            "E2189e8584b8d8e28:0:692"
          ],
          "condicoes": [
            "aplica-se aos tipos de sistema descritos no documento",
            "o retratamento eletrostático ocorre quando o óleo já tratado em outra unidade ainda não atende ao padrão de qualidade"
          ],
          "limites": [
            "os valores numéricos e critérios específicos de qualidade foram suprimidos",
            "o trecho não detalha dosagem química, balanços de massa ou balanços de energia"
          ]
        },
        {
          "proposicao": "As Unidades Estacionárias de Produção abrigam equipamentos de processamento primário dos fluidos dos poços e podem acumular funções operacionais associadas ao recebimento e apoio à produção, como gas-lift, lançamento de pigs e suprimento de energia a equipamentos submarinos.",
          "trechos": [
            "E2189e8584b8d8e28:692:1386"
          ],
          "condicoes": [
            "descrição vinculada a UEPs no contexto de produção offshore"
          ],
          "limites": [
            "não explicita a configuração de manifolds, risers ou malhas de controle",
            "não apresenta relações quantitativas entre recebimento, separação e utilidades"
          ]
        },
        {
          "proposicao": "A escolha do tipo de plataforma envolve viabilidade técnica e econômica, o que afeta o contexto físico onde o recebimento e a separação dos fluidos ocorrerão.",
          "trechos": [
            "E2189e8584b8d8e28:1386:2084"
          ],
          "condicoes": [
            "exemplo dado para plataformas fixas de aço"
          ],
          "limites": [
            "os números de lâmina d'água foram apagados",
            "o trecho trata mais de seleção de unidade do que de mecanismos de separação em estágios"
          ]
        }
      ]
    },
    {
      "id": "E09aad137514fcea4",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No processamento primário, a mistura proveniente dos poços é separada em óleo, gás e água; o óleo segue para refino, a água pode ser descartada no mar ou reciclada para injeção, e o gás pode ser usado para potência, para sistemas de injeção ou enviado para processamento em terra.",
          "trechos": [
            "E09aad137514fcea4:0:695",
            "E09aad137514fcea4:695:1395"
          ],
          "condicoes": [
            "descrição geral do processamento primário de petróleo offshore"
          ],
          "limites": [
            "não traz critérios detalhados de seleção entre as alternativas de destino",
            "não informa especificações ou limites ambientais numéricos"
          ]
        },
        {
          "proposicao": "A alimentação da planta de processamento primário pode ser intermitente ou em golfadas devido à combinação de longos trechos verticais dos risers com o uso de gas-lift em poços de baixa surgência, gerando oscilações de pressão e vazão ao longo do processo.",
          "trechos": [
            "E09aad137514fcea4:695:1395"
          ],
          "condicoes": [
            "contexto de produção offshore",
            "associado a risers e gas-lift"
          ],
          "limites": [
            "o trecho descreve mecanismo causal, mas não quantifica amplitudes, frequências ou faixas operacionais",
            "não detalha manifolds ou equipamentos específicos de amortecimento"
          ]
        },
        {
          "proposicao": "O estudo citado compara estratégias de controle preditivo para uma planta de separação trifásica sujeita a alimentação em golfadas, o que caracteriza um resultado de pesquisa aplicado a esse cenário e não uma regra geral de operação.",
          "trechos": [
            "E09aad137514fcea4:1395:2093",
            "E09aad137514fcea4:2093:2251"
          ],
          "condicoes": [
            "baseado em simulação em MATLAB e identificação de funções de transferência",
            "recorte específico de planta de separação trifásica com escoamento intermitente"
          ],
          "limites": [
            "o trecho não apresenta o desempenho final dos controladores",
            "não permite concluir superioridade universal de uma estratégia"
          ]
        }
      ]
    },
    {
      "id": "E894f8d59ef7f9f31",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O processamento primário existe porque a produção do campo costuma conter simultaneamente gás, óleo, água, sólidos e outras impurezas, enquanto o interesse econômico se concentra nos hidrocarbonetos.",
          "trechos": [
            "E894f8d59ef7f9f31:0:694"
          ],
          "condicoes": [
            "descrição geral ao longo da vida produtiva de um campo"
          ],
          "limites": [
            "não discrimina composições, frações ou comportamento por tipo de reservatório"
          ]
        },
        {
          "proposicao": "A finalidade do processamento primário é separar óleo, gás e água, condicionar os hidrocarbonetos para transferência a refinarias ou unidades de processamento de gás natural e tratar a água para um destino ambientalmente mais aceitável.",
          "trechos": [
            "E894f8d59ef7f9f31:694:1393"
          ],
          "condicoes": [
            "formulação descritiva da finalidade do processamento primário"
          ],
          "limites": [
            "não explicita estágios de separação nem critérios de controle de processo",
            "não traz requisitos normativos específicos"
          ]
        },
        {
          "proposicao": "Equipamentos inoperantes ou abaixo da eficiência esperada podem comprometer a qualidade dos fluidos separados, e o texto relaciona isso a envelhecimento, manutenção inadequada, problemas de projeto e modificações nas plantas; o levantamento em três plantas da Bacia de Campos é apresentado como observação empírica contextualizada.",
          "trechos": [
            "E894f8d59ef7f9f31:694:1393",
            "E894f8d59ef7f9f31:1393:2084"
          ],
          "condicoes": [
            "levantamento realizado em três plantas de separação em três tipos de UEPs",
            "contexto da Bacia de Campos"
          ],
          "limites": [
            "não permite generalizar a frequência ou a magnitude dos problemas para todas as plantas",
            "o trecho não informa indicadores quantitativos de perda de produção"
          ]
        }
      ]
    },
    {
      "id": "Ec0c7c916e7e881fb",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A complexidade da separação dos fluidos depende do tipo e da complexidade da plataforma, da existência de plataformas próximas, do tipo de fluido produzido e de outros fatores.",
          "trechos": [
            "Ec0c7c916e7e881fb:0:699"
          ],
          "condicoes": [
            "classificação apresentada para esquemas de processamento primário de fluidos"
          ],
          "limites": [
            "os fatores são citados de forma qualitativa, sem método de seleção ou ponderação"
          ]
        },
        {
          "proposicao": "Há diferentes arquiteturas de processamento: sem separação na unidade local; separação bifásica gás-líquido com envio do líquido óleo-água para outra unidade; e separação trifásica de gás, óleo e água livre, ainda sem remover a água emulsionada no óleo.",
          "trechos": [
            "Ec0c7c916e7e881fb:699:1398",
            "Ec0c7c916e7e881fb:1398:2098"
          ],
          "condicoes": [
            "classificação em tipos de sistema de produção"
          ],
          "limites": [
            "não detalha balanços, pressões de estágio ou arranjos internos de vasos",
            "o próprio texto declara não entrar em detalhes da emulsão"
          ]
        },
        {
          "proposicao": "O tratamento eletrostático aparece como complemento à separação trifásica para reduzir a água emulsionada e enquadrar o óleo em padrões de qualidade, podendo também existir uma planta dedicada apenas ao tratamento eletrostático da mistura óleo-água proveniente de outras unidades, enquanto a água deve receber destinação adequada segundo normas específicas.",
          "trechos": [
            "Ec0c7c916e7e881fb:1398:2098"
          ],
          "condicoes": [
            "aplica-se aos tipos 4 e 5 da classificação apresentada"
          ],
          "limites": [
            "o trecho não identifica quais normas específicas são essas",
            "não informa parâmetros de operação do tratador eletrostático"
          ]
        }
      ]
    },
    {
      "id": "Eab1d28c0b1e4e87d",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O processamento primário reúne operações voltadas à separação das fases dos fluidos produzidos e ao enquadramento de cada corrente a requisitos de comercialização, utilização ou descarte.",
          "trechos": [
            "Eab1d28c0b1e4e87d:2086:2492"
          ],
          "condicoes": [
            "definição geral no contexto de instalações de produção próximas ao campo"
          ],
          "limites": [
            "não explicita os requisitos nem sua base normativa",
            "não distingue critérios por corrente em detalhe"
          ]
        },
        {
          "proposicao": "O documento estrutura o domínio do processamento primário em separação gás-líquido, separação óleo-água, compressão e tratamento do gás, tratamento da água produzida e sistemas auxiliares de planta piloto, indicando utilidade potencial para organização didática do tema.",
          "trechos": [
            "Eab1d28c0b1e4e87d:696:1393",
            "Eab1d28c0b1e4e87d:1393:2086"
          ],
          "condicoes": [
            "baseado em sumário e descrição de planta piloto"
          ],
          "limites": [
            "o trecho é predominantemente estrutural e não traz explicações de mecanismo",
            "não permite extrair desempenho experimental dos equipamentos citados"
          ]
        },
        {
          "proposicao": "A planta piloto mencionada inclui sistemas de recombinação de petróleo, trocadores de calor, geração de vapor, água gelada, armazenamento e injeção de C5 e de produtos químicos, o que sugere interfaces relevantes entre separação, energia térmica e condicionamento químico.",
          "trechos": [
            "Eab1d28c0b1e4e87d:0:696",
            "Eab1d28c0b1e4e87d:1393:2086"
          ],
          "condicoes": [
            "contexto de instalação de teste e pesquisa"
          ],
          "limites": [
            "não informa como esses sistemas operam nem suas faixas operacionais",
            "por ser descrição de planta piloto, não deve ser convertida automaticamente em configuração típica de FPSO"
          ]
        }
      ]
    },
    {
      "id": "E26db318bd183666c",
      "pertinente": false,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O texto trata de simulação e avaliação técnica em etapa de Pre-FEED para um sistema offshore que produz essencialmente gás e condensado, integrando a unidade de processo a um sistema termodinâmico para geração de energia.",
          "trechos": [
            "E26db318bd183666c:0:699",
            "E26db318bd183666c:699:1397"
          ],
          "condicoes": [
            "estudo de caso de campo da bacia de Santos",
            "simulações em regime estacionário"
          ],
          "limites": [
            "o foco principal é integração energética e especificação preliminar da planta, não o recebimento de poços, manifolds e risers nem a separação multifásica óleo-gás-água em estágios",
            "os resultados numéricos estão parcialmente apagados"
          ]
        }
      ]
    }
